import {
    Table,
    StringColumn,
    DomainIdColumn,
    DomainPathColumn,
    ListColumn,
    BooleanColumn,
    GenericColumn,
    GuidColumn,
    TranslatedTextColumn,
} from '@servicenow/sdk/core'

export const user_criteria = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'User Criteria',
    name: 'user_criteria',
    schema: {
        name: StringColumn({
            label: 'Name',
            mandatory: true,
            maxLength: 100,
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the user criteria belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        group: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Groups',
            maxLength: 1024,
            referenceTable: 'sys_user_group',
        }),
        advanced: BooleanColumn({
            default: false,
            label: 'Advanced',
        }),
        role: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Roles',
            maxLength: 1024,
            referenceTable: 'sys_user_role',
        }),
        department: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Departments',
            maxLength: 1024,
            referenceTable: 'cmn_department',
        }),
        match_all: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If set to true, only users who match an element of each condition are given access. If set to false, at least one of the set conditions should be met in order to allow access to the user.',
                    label: 'Match All',
                    plural: 'Match All',
                    language: 'en',
                },
            ],
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        location: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Locations',
            maxLength: 1024,
            referenceTable: 'cmn_location',
        }),
        company: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Companies',
            maxLength: 1024,
            referenceTable: 'core_company',
        }),
        script: GenericColumn({
            columnType: 'script_plain',
            default: `/** Scripted User Criteria is not cached, and evaluated everytime, so performance is dependent on the script.
* Populate \`answer\` with true/false or evaluate to true/false
* The script is evaluated in the scope the user criteria is defined
* Don't use \`current\` in the script or populate the variable
* Don't use \`gs.getUser()\` or  \`gs.getUserID()\`, 
* instead use \`user_id\` which contains the user sys_id against whom the evaluation is happening.
*/`,
            label: 'Script',
            maxLength: 8000,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        short_description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Short Description',
            maxLength: 4000,
        }),
        user: ListColumn({
            attributes: {
                no_email: true,
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Users',
            maxLength: 1024,
            referenceTable: 'sys_user',
        }),
    },
})
